	@Override
	public void setupAnim(State state) {
		super.setupAnim(state);
		head.yRot += state.yRot * 0.017453292F * 1.0F;
		head.xRot += state.xRot * 0.017453292F * 1.0F;
		arm_l.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.9F * state.walkAnimationSpeed;
		arm_l.zRot += Mth.sin(state.ageInTicks * 0.09F + 0.0F) * (0.03F + 0.0F * state.walkAnimationSpeed);
		leg_l.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 1.1F * state.walkAnimationSpeed;
		arm_r.xRot += -Mth.sin(state.attackTime * 3.1415927F) * 1.3F;
		arm_r.zRot += Mth.sin(state.ageInTicks * 0.09F + 3.141592653589793F) * (0.03F + 0.0F * state.walkAnimationSpeed);
		leg_r.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 1.1F * state.walkAnimationSpeed;
		ear_l.zRot += Mth.sin(state.ageInTicks * 0.14F + 0.0F) * (0.05F + 0.0F * state.walkAnimationSpeed);
		ear_r.zRot += Mth.sin(state.ageInTicks * 0.14F + 1.3F) * (0.05F + 0.0F * state.walkAnimationSpeed);
	}
